        vector<vector<pair<int,int>>> graph(n);
        for(auto& road:roads){
            graph[road[0]-1].push_back({
                road[1]-1,road[2]
            });
            graph[road[1]-1].push_back({
                road[0]-1,road[2]
            });
        }
        vector<bool> visited(n);
        queue<int> queue;
        queue.push(0);
        visited[0]=true;
        int answer=INT_MAX;
        while(!queue.empty()){
            int node=queue.front();
            queue.pop();
            for(auto [next,distance]:graph[node]){
                answer=min(answer,distance);
                if(!visited[next]){
                    visited[next]=true;
                    queue.push(next);
                }
            }
        }
